using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Object=UnityEngine.Object;
namespace RedCliffMystery.EditorTools {public static partial class CharacterPartsWorkbench {
static string Root=>"Assets/Art/Characters/Parts20261018/"+Target;
static string Reports=>Path.Combine(Dir,Target,"Review");
static Texture2D Map(string name,bool normal=false,bool linear=false){string p=Root+"/Maps/"+name+".png";var i=(TextureImporter)AssetImporter.GetAtPath(p);i.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;i.sRGBTexture=!normal&&!linear;i.maxTextureSize=Target=="Seolpyeong"?4096:2048;i.textureCompression=TextureImporterCompression.CompressedHQ;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(p);}
[MenuItem("Tools/Character Parts/Apply Current Character")]
public static void ApplyCurrent(){Directory.CreateDirectory(Reports);File.WriteAllText(Path.Combine(Reports,"apply-status.txt"),"QUEUED");EditorApplication.delayCall+=()=>{try{File.WriteAllText(Path.Combine(Reports,"apply-status.txt"),"STARTED");ApplyCore();File.WriteAllText(Path.Combine(Reports,"apply-status.txt"),"COMPLETE");}catch(Exception e){File.WriteAllText(Path.Combine(Reports,"apply-status.txt"),"FAILED\n"+e);Debug.LogException(e);}};}
static void ApplyCore(){if(EditorApplication.isPlaying)throw new Exception("Exit Play first");var mo=Motion();var f=mo.transform.Find("Model").GetComponent<MeshFilter>();var re=f.GetComponent<MeshRenderer>();var prior=JsonUtility.ToJson(mo);var rootBefore=string.Join("\n",mo.transform.parent.GetComponents<Component>().Select(x=>EditorJsonUtility.ToJson(x)));
string backup=Path.Combine(Reports,"before.unity");if(!File.Exists(backup))File.Copy(mo.gameObject.scene.path,backup);var data=JsonUtility.FromJson<SurfaceData>(File.ReadAllText(Path.Combine(Dir,Target,"Source/current-game-surface.json")));var importer=(ModelImporter)AssetImporter.GetAtPath(Root+"/Parts.fbx");importer.isReadable=true;importer.importAnimation=false;importer.SaveAndReimport();var source=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Parts.fbx");var tmp=Object.Instantiate(source);
try{var filters=tmp.GetComponentsInChildren<MeshFilter>();var list=filters.Select(x=>new CombineInstance{mesh=x.sharedMesh,transform=x.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name=Target+"_Parts_Game",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(list,true,true);var vertices=mesh.vertices;var normals=mesh.normals;var tangents=mesh.tangents;for(int i=0;i<vertices.Length;i++){if(Target=="Seolpyeong")continue;vertices[i].x=-vertices[i].x;if(normals.Length==vertices.Length)normals[i].x=-normals[i].x;if(tangents.Length==vertices.Length){tangents[i].x=-tangents[i].x;tangents[i].w=-tangents[i].w;}}var triangles=mesh.triangles;for(int i=0;i<triangles.Length;i+=3){if(Target=="Seolpyeong")continue;int t=triangles[i+1];triangles[i+1]=triangles[i+2];triangles[i+2]=t;}mesh.vertices=vertices;mesh.normals=normals;if(tangents.Length==vertices.Length)mesh.tangents=tangents;mesh.triangles=triangles;mesh.RecalculateBounds();if(mesh.bounds.size.y<1.4||mesh.bounds.size.y>2.2||Mathf.Abs(mesh.bounds.min.y)>.05)throw new Exception("Axis/scale failed "+mesh.bounds);
string mp=Root+"/Parts_Game.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(mp);if(saved==null){AssetDatabase.CreateAsset(mesh,mp);saved=mesh;}else{EditorUtility.CopySerialized(mesh,saved);Object.DestroyImmediate(mesh);}string matpath=Root+"/Parts.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matpath);if(mat==null){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,matpath);}mat.SetTexture("_BaseMap",Map("BaseColor"));mat.SetColor("_BaseColor",Color.white);mat.SetTexture("_BumpMap",Map("Normal",true));mat.SetFloat("_BumpScale",1);mat.EnableKeyword("_NORMALMAP");mat.SetTexture("_MetallicGlossMap",Map("MetallicSmoothness",false,true));mat.EnableKeyword("_METALLICSPECGLOSSMAP");mat.SetFloat("_Metallic",1);mat.SetFloat("_Smoothness",1);if(Target=="Seolpyeong"){mat.SetFloat("_AlphaClip",1);mat.SetFloat("_Cutoff",.18f);mat.EnableKeyword("_ALPHATEST_ON");mat.SetFloat("_Cull",0);mat.SetFloat("_EnvironmentReflections",0);mat.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");mat.renderQueue=2450;}
Undo.RecordObjects(new Object[]{f,re,f.transform},"Apply refined character parts");f.sharedMesh=saved;re.sharedMaterials=new[]{mat};f.transform.localPosition=Vector3.zero;f.transform.localRotation=Quaternion.identity;f.transform.localScale=Vector3.one;if(JsonUtility.ToJson(mo)!=prior)throw new Exception("Motion settings changed");if(rootBefore!=string.Join("\n",mo.transform.parent.GetComponents<Component>().Select(x=>EditorJsonUtility.ToJson(x))))throw new Exception("Root changed");PrefabUtility.SaveAsPrefabAsset(mo.gameObject,Root+"/Visual.prefab");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(mo.gameObject.scene);EditorSceneManager.SaveScene(mo.gameObject.scene);File.WriteAllText(Path.Combine(Reports,"apply.txt"),"PASS "+saved.vertexCount+" vertices bounds="+saved.bounds+" motion settings, root interaction and collider unchanged");}finally{Object.DestroyImmediate(tmp);}}
[MenuItem("Tools/Character Parts/Validate Motion")]
public static void ValidateCurrent(){Directory.CreateDirectory(Reports);var clone=Object.Instantiate(Motion().gameObject);clone.transform.position=new Vector3(500,500,500);try{var m=clone.GetComponent<VarcoIdleMotion>();m.InitializeForPreview();m.Sample(0);var f=clone.transform.Find("Model").GetComponent<MeshFilter>();var rest=f.sharedMesh.vertices;m.Sample(1);var idle=f.sharedMesh.vertices;int moving=rest.Where((v,i)=>(v-idle[i]).sqrMagnitude>1e-12f).Count();m.StartSpeech("아",-.07f);m.Sample(0);var sp=f.sharedMesh.vertices;int lips=rest.Where((v,i)=>(v-sp[i]).sqrMagnitude>1e-12f).Count();m.StartSpeech("아",-10);m.Sample(0);bool closes=rest.SequenceEqual(f.sharedMesh.vertices);if(moving==0||(m.DisableLipMotion?lips!=0:lips==0)||!closes)throw new Exception("Motion failure");File.WriteAllText(Path.Combine(Reports,"motion.txt"),"PASS idle="+moving+" mouth="+lips+" lipMotionDisabled="+m.DisableLipMotion+" closes="+closes);}finally{Object.DestroyImmediate(clone);}}
[MenuItem("Tools/Character Parts/Review Current Character")]
public static void ReviewCurrent(){if(!EditorApplication.isPlaying)throw new Exception("Play required");var mo=Motion();var player=Object.FindAnyObjectByType<Investigation.FirstPersonInvestigator>();var session=Object.FindAnyObjectByType<Investigation.InvestigationSession>();if(Target=="CaoCao"){if(!mo.gameObject.activeInHierarchy)session.VisitCommandTent();session.view.HideModal();}else session.CloseModal();player.enabled=false;var camera=player.viewCamera;float h=mo.transform.Find("Model").GetComponent<Renderer>().bounds.size.y/Mathf.Abs(mo.transform.lossyScale.y);string view=File.ReadAllText(Path.Combine(Dir,"active-view.txt")).Trim();Vector3 local=new Vector3(.15f,h*.85f,-h*1.3f),aim=new Vector3(0,h*.52f,0);if(view=="portrait"){local=new Vector3(.18f,h*1.02f,-.60f);aim=new Vector3(0,h*.875f,0);}if(view=="face"){local=new Vector3(.04f,h*.91f,-.55f);aim=new Vector3(0,h*.88f,0);}if(view=="hands"){local=new Vector3(h*.23f,h*.48f,-h*.38f);aim=new Vector3(h*.21f,h*.47f,0);}if(view=="shoulders"){local=new Vector3(.08f,h*.78f,-h*.55f);aim=new Vector3(0,h*.76f,0);}if(view=="back"){local=new Vector3(.15f,h*.85f,h*1.2f);}if(view=="side"){local=new Vector3(h*1.1f,h*.8f,-.15f);}if(view=="interaction"){local=new Vector3(.05f,h*.8f,-1.0f);aim=new Vector3(0,h*.65f,0);}var pos=mo.transform.TransformPoint(local);var arrival=new GameObject("TemporaryCharacterReview");arrival.transform.position=pos-Vector3.up*camera.transform.localPosition.y;arrival.transform.rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(mo.transform.TransformPoint(aim)-pos,Vector3.up));player.TeleportTo(arrival.transform);Object.Destroy(arrival);camera.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(mo.transform.TransformPoint(aim)-pos));Physics.SyncTransforms();Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}
[MenuItem("Tools/Character Parts/Check Interaction")]
public static void CheckInteraction(){if(Target=="CaoCao"){var tent=Object.FindAnyObjectByType<Investigation.InvestigationSession>();tent.VisitCommandTent();if(!tent.BlocksMovement||tent.view.title.text!="조조")throw new Exception("Command tent dialogue failed");File.WriteAllText(Path.Combine(Reports,"interaction.txt"),"PASS actual command tent visit dialogue; CaoCao uses tent dialogue rather than NPC ray target");return;}var p=Object.FindAnyObjectByType<Investigation.FirstPersonInvestigator>();var t=p.FindTarget();if(t==null||t.transform!=Motion().transform.parent)throw new Exception("Aim does not reach character");var s=Object.FindAnyObjectByType<Investigation.InvestigationSession>();t.Interact(s);if(!s.BlocksMovement)throw new Exception("Interaction failed");File.WriteAllText(Path.Combine(Reports,"interaction.txt"),"PASS player ray and interaction modal");}
}}




